m, n = map(int, input().split())
grid = [[int(x) for x in input().split()] for _ in range(m)]

for r in range(m):
    for c in range(n):
        if r == 0 and c == 0:
            continue
        if r == 0:
            grid[r][c] += grid[r][c - 1]        # only from the left
        elif c == 0:
            grid[r][c] += grid[r - 1][c]        # only from above
        else:
            grid[r][c] += min(grid[r - 1][c], grid[r][c - 1])

print(grid[m - 1][n - 1])

from collections import deque

r, c = map(int, input().split())
grid = [list(input().strip()) for _ in range(r)]

islands = 0
for i in range(r):
    for j in range(c):
        if grid[i][j] != "1":
            continue
        islands += 1                    # a new island
        grid[i][j] = "0"
        queue = deque([(i, j)])
        while queue:
            x, y = queue.popleft()
            for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nx, ny = x + dx, y + dy
                if 0 <= nx < r and 0 <= ny < c and grid[nx][ny] == "1":
                    grid[nx][ny] = "0"  # mark as visited
                    queue.append((nx, ny))

print(islands)

w1 = input()
w2 = input()
n, m = len(w1), len(w2)

dp = [[0] * (m + 1) for _ in range(n + 1)]
for i in range(n + 1):
    dp[i][0] = i
for j in range(m + 1):
    dp[0][j] = j

for i in range(1, n + 1):
    for j in range(1, m + 1):
        if w1[i - 1] == w2[j - 1]:
            dp[i][j] = dp[i - 1][j - 1]
        else:
            dp[i][j] = 1 + min(dp[i - 1][j],        # delete
                               dp[i][j - 1],        # insert
                               dp[i - 1][j - 1])    # replace

print(dp[n][m])
